  // Render helper — returns an <img> for the stat's custom art if available,
  // otherwise falls back to the raw emoji. The opts.size controls render
  // size in CSS px; opts.eager loads immediately (use for above-the-fold).
  function statIconHtml(st, opts) {
    opts = opts || {};
    const sz = opts.size || 32;
    if (st && st.iconImg) {
      const cls = 'stat-icon-img' + (opts.cls ? ' ' + opts.cls : '');
      return '<img class="' + cls + '" src="' + st.iconImg + '" alt="' +
        (st.label ? st.label.replace(/"/g, '') : '') + '" ' +
        'style="width:' + sz + 'px;height:' + sz + 'px" ' +
        'draggable="false" loading="' + (opts.eager ? 'eager' : 'lazy') + '" decoding="async">';
    }
    return st && st.icon ? st.icon : '';
  }
  // For elements that previously held a single emoji glyph via .textContent.
  function setStatIcon(el, st, sizePx) {
    if (!el) return;
    el.innerHTML = statIconHtml(st, { size: sizePx || 32, eager: true });
  }

  // ── HABIT ICON HELPERS ───────────────────────────────────
  // Mirrors the stat-icon pattern. getHabitIcon returns the PNG path if
  // the curated habit has a mapping; null otherwise. Custom user habits
  // ALWAYS return null — they keep their user-chosen emoji. habitIconHtml
  // returns the proper render markup (img tag OR escaped emoji string).
  // setHabitIcon writes the markup into an existing element via innerHTML.
  // v3 Phase 1z.270 — Custom habit icon support.
  // Resolution order:
  //   1. Explicit habit.iconKey → lookup in HABIT_ICON_BY_KEY (works for
  //      both custom and preset habits — e.g. a preset whose user
  //      overrode the default icon)
  //   2. Preset habit name in HABIT_ICONS (legacy path; unchanged)
  //   3. Custom habits without iconKey → null → habitIconHtml falls
  //      through to habit.emoji (legacy custom path; unchanged)
  // No regression for legacy custom habits — they have no iconKey and
  // hit the same null path that returned today.
  function getHabitIcon(habit) {
    if (!habit) return null;
    if (habit.iconKey && typeof HABIT_ICON_BY_KEY !== 'undefined' && HABIT_ICON_BY_KEY[habit.iconKey]) {
      return HABIT_ICON_BY_KEY[habit.iconKey];
    }
    if (habit.custom) return null;
    return (habit.name && HABIT_ICONS[habit.name]) || null;
  }
  function habitIconHtml(habit, opts) {
    opts = opts || {};
    const sz   = opts.size || 32;
    const path = getHabitIcon(habit);
    if (path) {
      const cls = 'habit-icon-img' + (opts.cls ? ' ' + opts.cls : '');
      const alt = (habit.name || '').replace(/"/g, '');
      return '<img class="' + cls + '" src="' + path + '" alt="' + alt + '" ' +
        'style="width:' + sz + 'px;height:' + sz + 'px" ' +
        'draggable="false" loading="' + (opts.eager ? 'eager' : 'lazy') + '" decoding="async">';
    }
    return habit && habit.emoji ? habit.emoji : '';
  }
  function setHabitIcon(el, habit, sizePx) {
    if (!el) return;
    const path = getHabitIcon(habit);
    if (path) {
      el.innerHTML = habitIconHtml(habit, { size: sizePx || 32, eager: true });
    } else {
      el.textContent = habit && habit.emoji ? habit.emoji : '';
    }
  }

  // v2.1 — Stat taglines for the Stats tab onboarding subtitles.
  // One-word identity that conveys what each stat actually represents
  // for casual users who haven't memorized the STR/VIT/INT/FOCUS/WILL/WLT
  // canon. Stays uppercase to match the abbr typography.
  const STAT_TAGLINES = {
    STR:   'BODY',
    VIT:   'RECOVERY',
    INT:   'MIND',
    FOCUS: 'PRESENCE',
    WILL:  'DISCIPLINE',
    WLT:   'WEALTH',
  };

  // Builds the dominant-alignment / class card that sits above the
  // OSRS stat-grid on the Stats tab. Three states:
  //   1. Awakened (currentClass set + not CIVILIAN): show class name,
  //      class glyph, class color, class tagline from CLASSES[id].desc
  //   2. Civilian with progress: show "LEANING: <CLASS>" of top stat,
  //      "<STAT> DOMINANT" sub, prompt "Reach Lv5 to Awaken"
  //   3. Civilian with no progress: "CIVILIAN" + onboarding prompt
  function _buildAlignmentCard() {
    const card = document.createElement('div');
    card.className = 'alignment-card';

    // Determine state.
    const ranked = STATS.map(st => ({
      id:  st.id,
      lv:  statLevel(stats[st.id]?.pts || 0),
      pts: stats[st.id]?.pts || 0,
    })).sort((a, b) => (b.lv - a.lv) || (b.pts - a.pts));
    const topStat = ranked[0];
    const hasProgress = topStat && topStat.pts > 0;

    const statClassMap = { STR:'STR', VIT:'VIT', INT:'INT', FOCUS:'FOCUS', WILL:'WILL', WLT:'WLT' };
    let displayClassId = null;
    let stateLabel     = '';
    let primaryName    = '';
    let subtext        = '';
    let pathText       = '';

    if (currentClass && currentClass !== 'CIVILIAN') {
      displayClassId = currentClass;
      const def = CLASSES[currentClass];
      stateLabel  = 'CLASS';
      primaryName = (def && def.name ? def.name : currentClass).toUpperCase();
      subtext     = def && def.desc ? def.desc : '';
      pathText    = '';
    } else if (hasProgress) {
      // Civilian with progress — leaning toward the top stat's class.
      displayClassId = statClassMap[topStat.id] || null;
      const def = displayClassId ? CLASSES[displayClassId] : null;
      const cName = (def && def.name) ? def.name.toUpperCase() : topStat.id;
      stateLabel  = 'LEANING';
      primaryName = cName + '-LEANING';
      subtext     = topStat.id + ' DOMINANT';
      pathText    = ''; // Progress bar below conveys the path now.
    } else {
      // First-launch Civilian, no XP anywhere yet.
      displayClassId = null;
      stateLabel  = 'CLASS';
      primaryName = 'CIVILIAN';
      subtext     = 'You have not been Awakened yet.';
      pathText    = 'Train any stat to Lv5 to find your path.';
    }

    // Color anchor — use class color when available, else accent purple.
    const color = (displayClassId && CLASSES[displayClassId] && CLASSES[displayClassId].color) || '#8b5cf6';
    card.style.setProperty('--alignment-color', color);

    // v2.1 — use the real class-emblem PNG instead of the emoji glyph.
    // Map class id → /assets/habit-icons/icon-class-<role>.png.
    // STR=warrior, VIT=ranger, INT=mage, FOCUS=assassin, WILL=paladin,
    // WLT=merchant, SAGE=sage, CIVILIAN=civilian.
    const CLASS_ICON_FILES = {
      STR:      'icon-class-warrior.png',
      VIT:      'icon-class-ranger.png',
      INT:      'icon-class-mage.png',
      FOCUS:    'icon-class-assassin.png',
      WILL:     'icon-class-paladin.png',
      WLT:      'icon-class-merchant.png',
      SAGE:     'icon-class-sage.png',
      CIVILIAN: 'icon-class-civilian.png',
    };
    const iconFile = (displayClassId && CLASS_ICON_FILES[displayClassId]) || CLASS_ICON_FILES.CIVILIAN;
    const iconSrc  = 'assets/habit-icons/' + iconFile;
    const iconHTML = '<img class="alignment-card-icon" src="' + iconSrc + '" alt="" ' +
                     'draggable="false" loading="lazy" decoding="async">';

    // v2.1 — Next-milestone progress bar inside the alignment card.
    // Replaces the standalone NEXT STAT BONUS section. For Civilian-
    // with-progress users, targets the dominant stat's Lv5 Awakening
    // threshold. For Awakened users, targets the closest stat-bonus
    // threshold across all stats (same logic the old card used).
    let progressHTML = '';
    if (hasProgress) {
      let targetStat   = topStat;
      let targetLevel  = 5;
      let targetReward = 25; // STAT_BONUS_THRESHOLDS[Lv5] = +25 XP

      if (currentClass && currentClass !== 'CIVILIAN') {
        // Awakened — find the closest stat-bonus threshold not yet
        // awarded across any stat. Mirrors the prior NEXT STAT BONUS
        // candidate scan.
        const candidates = [];
        STATS.forEach(st => {
          const curLv = statLevel(stats[st.id]?.pts || 0);
          STAT_BONUS_THRESHOLDS.forEach(thr => {
            const key = st.id + '_' + thr.level;
            if (!statBonuses.has(key)) {
              candidates.push({
                stId: st.id, stLv: curLv, stPts: stats[st.id]?.pts || 0,
                thrLevel: thr.level, thrPts: thr.pts,
              });
            }
          });
        });
        candidates.sort((a, b) => (a.thrLevel - a.stLv) - (b.thrLevel - b.stLv));
        if (candidates.length) {
          const nx = candidates[0];
          targetStat   = { id: nx.stId, lv: nx.stLv, pts: nx.stPts };
          targetLevel  = nx.thrLevel;
          targetReward = nx.thrPts;
        }
      }

      // Pct of progress from baseline (current full level start) to target.
      // For Civilian: ratio of current level toward Lv5.
      const pct = Math.min(100, Math.round((targetStat.lv / targetLevel) * 100));
      const remainingLvs = Math.max(0, targetLevel - targetStat.lv);
      const goalText = (currentClass && currentClass !== 'CIVILIAN')
        ? targetStat.id + ' Lv' + targetLevel
        : 'AWAKEN at ' + targetStat.id + ' Lv' + targetLevel;

      progressHTML =
        '<div class="alignment-progress">' +
          '<div class="alignment-progress-head">' +
            '<span class="alignment-progress-label">' + esc(goalText) + '</span>' +
            '<span class="alignment-progress-reward">+' + targetReward + ' XP</span>' +
          '</div>' +
          '<div class="alignment-progress-track">' +
            '<div class="alignment-progress-fill" style="width:' + pct + '%"></div>' +
          '</div>' +
          '<div class="alignment-progress-axis">' +
            '<span>Lv.' + targetStat.lv + '</span>' +
            '<span>' + (remainingLvs === 0 ? 'READY' : remainingLvs + ' lv to go') + '</span>' +
            '<span>Lv.' + targetLevel + '</span>' +
          '</div>' +
        '</div>';
    }

    card.innerHTML =
      '<div class="alignment-card-bg" aria-hidden="true"></div>' +
      '<div class="alignment-card-head">' +
        '<span class="alignment-card-label">' + esc(stateLabel) + '</span>' +
        iconHTML +
      '</div>' +
      '<div class="alignment-card-name">' + esc(primaryName) + '</div>' +
      (subtext ? '<div class="alignment-card-sub">' + esc(subtext) + '</div>' : '') +
      (pathText ? '<div class="alignment-card-path">' + esc(pathText) + '</div>' : '') +
      progressHTML;

    return card;
  }

